'use strict';
const $ = id => document.getElementById(id);
let csrf = '', state = null;
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const clock = value => new Date(value * 1000).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'});
function toast(message){$('toast').textContent=message;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),5000);}
async function api(path, body){const options={credentials:'same-origin',headers:{}};if(body!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-Sentinel-CSRF':csrf};options.body=JSON.stringify(body);}const response=await fetch(path,options);let result=await response.json();if(!response.ok){if(response.status===401){$('console').classList.add('hidden');$('login-panel').classList.remove('hidden');$('logout').classList.add('hidden');$('connection').textContent='Authentication required';}throw new Error(result.error||'Request failed');}return result;}
async function refresh(){try{state=await api('/api/state');csrf=state.identity.csrf;$('login-panel').classList.add('hidden');$('console').classList.remove('hidden');$('logout').classList.remove('hidden');$('connection').textContent='Local gateway data';render();}catch(error){$('connection').textContent=state?'Connection lost · data may be stale':'Authentication required';}}
function render(){const active=state.sessions.filter(s=>s.status==='active');const pending=state.approvals.filter(a=>a.status==='pending');$('allowed').textContent=state.counts.ALLOW||0;$('denied').textContent=state.counts.DENY||0;$('active').textContent=active.length;$('pending-count').textContent=pending.length;$('nav-pending').textContent=pending.length;renderEvents();
$('approval-list').innerHTML=pending.length?pending.map(a=>`<article class="approval-item"><span class="badge REQUIRE_APPROVAL">REQUIRES REVIEW</span><h3>${esc(a.operation)} → ${esc(a.resource)}</h3><p>${esc(a.task)}</p><p>Payload SHA-256<br>${esc(a.body_sha256)}</p><small>Expires ${clock(a.expires_at)} · event #${a.event_id}</small><div class="buttons"><button class="primary" data-approve="${esc(a.id)}">Approve once</button><button class="quiet" data-deny="${esc(a.id)}">Deny</button></div></article>`).join(''):'<p class="empty">No requests awaiting review.<br>New privileged requests appear here.</p>';
$('session-list').innerHTML=state.sessions.length?state.sessions.map(s=>`<article class="session-card"><h3>${esc(s.task_id)} <span class="tag">${esc(s.status.toUpperCase())}</span></h3><p>Expires ${clock(s.expires_at)} · ${s.grants.length} exact grants</p><p>${s.tainted?'Protected data observed · output flow blocked':'Task-scoped authority · no native executor'}</p><details><summary>Inspect task permissions</summary><ul>${s.grants.map(g=>`<li>${esc(g.operation)} · ${esc(g.resource)}${g.approval?' · approval required':''}</li>`).join('')}</ul></details>${s.status==='active'?`<div class="buttons"><button class="quiet" data-provenance="${esc(s.task_id)}">Test protected-data flow</button><button class="quiet" data-revoke="${esc(s.task_id)}">Revoke session</button></div>`:''}</article>`).join(''):'<p class="empty">No sessions started in this server process.</p>';
$('controls').innerHTML=Object.entries(state.controls).map(([name,value])=>`<div class="control"><span>${esc(name.replaceAll('_',' '))}</span><span>${esc(value)}</span></div>`).join('');
const bench=state.benchmarks;$('benchmark').innerHTML=bench?`<p>Seed ${esc(bench.seed)} · ${esc(bench.repetitions)} repetitions · deterministic synthetic workload</p><table><thead><tr><th>Research arm</th><th>Unauthorized executed</th><th>Completion</th></tr></thead><tbody>${Object.entries(bench.arms||{}).map(([name,m])=>`<tr><td>${esc(name)}</td><td class="metric">${m.unauthorized_executed} / ${m.unauthorized_attempts}</td><td class="metric">${m.completed_tasks} / ${m.tasks}</td></tr>`).join('')}</tbody></table><p>Comparison arms are isolated research simulators. No bypass mode exists in the application.</p>`:'<p class="empty">No Phase 2 benchmark results recorded.<br>Run python -m benchmarks.phase2 to generate measurements.</p>';
$('admin-events').innerHTML=state.admin_events.length?state.admin_events.map(e=>`<div class="admin-line"><span>${clock(e.timestamp)} · ${esc(e.actor)} · ${esc(e.action)}</span><span>${esc(e.result)}</span></div>`).join(''):'<p class="empty">No administrator events.</p>';}
function renderEvents(){if(!state)return;const query=$('search').value.toLowerCase(),decision=$('decision-filter').value;const events=state.events.filter(e=>(!decision||e.decision===decision)&&JSON.stringify(e).toLowerCase().includes(query));$('event-rows').innerHTML=events.map(e=>`<tr><td><span class="event-id">#${e.id}</span>${esc(e.operation)}<span class="sub">${esc(e.reason)}</span></td><td><span class="sub">${esc(e.task)}</span></td><td><span class="badge ${esc(e.decision)}">${esc(e.decision)}</span></td><td>${clock(e.timestamp)}</td><td><button class="inspect" data-inspect="${e.id}" aria-label="Inspect event ${e.id}">↗</button></td></tr>`).join('');$('event-empty').classList.toggle('hidden',events.length>0);$('event-empty').textContent=state.events.length?'No events match these filters.':'No security events yet. Run a controlled demonstration to create real runtime activity.';$('event-total').textContent=`${events.length} events shown`;$('updated').textContent='Updated '+new Date().toLocaleTimeString();}
$('login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const result=await api('/api/login',{password:$('password').value});csrf=result.csrf;$('password').value='';$('login-error').textContent='';await refresh();}catch(error){$('login-error').textContent=error.message;}finally{button.disabled=false;}});
$('run-demo').addEventListener('click',async event=>{event.target.disabled=true;try{const result=await api('/api/demo',{});toast(result.completed?'Authorized task completed. Prohibited requests blocked; approval queued.':'Task did not complete. Inspect the events.');await refresh();}catch(error){toast(error.message);}finally{event.target.disabled=false;}});
$('logout').addEventListener('click',async()=>{try{await api('/api/logout',{});state=null;csrf='';await refresh();}catch(error){toast(error.message);}});
$('search').addEventListener('input',renderEvents);$('decision-filter').addEventListener('change',renderEvents);$('close-detail').addEventListener('click',()=>$('event-dialog').close());
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;const d=button.dataset;if(d.inspect){$('event-detail').textContent=JSON.stringify(state.events.find(e=>e.id===Number(d.inspect)),null,2);$('event-dialog').showModal();return;}if(!(d.approve||d.deny||d.revoke||d.provenance))return;button.disabled=true;try{if(d.approve||d.deny){const result=await api('/api/approval',{id:d.approve||d.deny,approve:!!d.approve});toast(result.result?`Approved: ${result.result.decision}. Replay: ${result.replay.decision}.`:'Approval denied.');}else if(d.revoke){await api('/api/revoke',{task:d.revoke});toast('Task revoked and runtime stopped.');}else{const result=await api('/api/provenance',{task:d.provenance});toast(`Protected read: ${result.read_decision}. Write: ${result.write.decision}. Transfer: ${result.network.decision}.`);}await refresh();}catch(error){toast(error.message);}finally{button.disabled=false;}});
refresh();setInterval(refresh,5000);
